SELECT r.id,outbound.ingress_node_id,r.targets,r.user_id,u.quota_epoch,COALESCE(extract(epoch FROM LEAST(u.expires_at,u.next_reset_at))::bigint,0),r.protocol FROM rules r JOIN user_entitlements u ON u.id=r.user_id JOIN rule_outbound_routes outbound ON outbound.rule_id=r.id JOIN user_nodes ingress ON ingress.user_id=r.user_id AND ingress.node_id=outbound.ingress_node_id LEFT JOIN node_groups ig ON ig.id=r.ingress_group_id LEFT JOIN user_node_groups iug ON iug.group_id=r.ingress_group_id AND iug.user_id=r.user_id WHERE outbound.egress_node_id=$1 AND (r.ingress_group_id IS NULL OR ig.enabled AND iug.user_id IS NOT NULL AND $2::integer >= $3::integer) AND EXISTS(SELECT 1 FROM nodes source WHERE source.id=outbound.ingress_node_id AND source.ingress_enabled) AND r.enabled AND u.enabled AND (u.expires_at IS NULL OR u.expires_at>now()) ORDER BY r.id,outbound.ingress_node_id